const MAX_SKEW_SECONDS = 300;
const SCHEME = 'v1=';

const { timestamp, signature, rawBody, expectedSignature } = $input.first().json;

const given = String(signature ?? '');
const provided = given.startsWith(SCHEME) ? given.slice(SCHEME.length) : '';
let difference = provided.length === expectedSignature.length ? 0 : 1;
if (difference === 0) {
  for (let i = 0; i < expectedSignature.length; i++) {
    difference |= provided.charCodeAt(i) ^ expectedSignature.charCodeAt(i);
  }
}

const sentAt = /^\d+$/.test(String(timestamp)) ? Number(timestamp) : NaN;
const fresh = Math.abs(Date.now() / 1000 - sentAt) <= MAX_SKEW_SECONDS;

let body = null;
if (difference === 0 && fresh) {
  try {
    body = JSON.parse(rawBody);
  } catch {
    body = null;
  }
}

return [{ json: { valid: body !== null, body } }];
